import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Поддержка","description":"","frontmatter":{},"headers":[],"relativePath":"guide/support.md","filePath":"guide/support.md","lastUpdated":0}`),a={name:`guide/support.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="поддержка" tabindex="-1">Поддержка <a class="header-anchor" href="#поддержка" aria-label="Permalink to “Поддержка”">​</a></h1><h2 id="куда-обращаться" tabindex="-1">Куда обращаться <a class="header-anchor" href="#куда-обращаться" aria-label="Permalink to “Куда обращаться”">​</a></h2><table tabindex="0"><thead><tr><th>Что случилось</th><th>Куда</th><th>Что приложить</th></tr></thead><tbody><tr><td>Идея, пожелание, «хотелось бы»</td><td><a href="/yamapper/suggest">Предложить функцию</a> или <a href="https://github.com/vibecodinguser/yamapper/discussions/1" target="_blank" rel="noreferrer">обсуждение идей</a></td><td>Описание задачи и пример использования</td></tr><tr><td>Что-то сломалось, ошибка</td><td><a href="https://github.com/vibecodinguser/yamapper/issues" target="_blank" rel="noreferrer">Issues</a></td><td>Шаги, версия расширения, версия браузера, скриншот</td></tr><tr><td>Вопрос по работе</td><td><a href="https://github.com/vibecodinguser/yamapper/discussions" target="_blank" rel="noreferrer">Discussions</a></td><td>Что делали и что ожидали</td></tr><tr><td>Уязвимость или утечка данных</td><td>Напрямую автору через профиль <a href="https://github.com/vibecodinguser" target="_blank" rel="noreferrer">vibecodinguser</a></td><td>Описание без публичных деталей</td></tr></tbody></table><p>Не публикуйте в открытых Issues токены, содержимое Диска и персональные данные из геофайлов.</p><h2 id="как-собрать-полезныи-отчет" tabindex="-1">Как собрать полезный отчёт <a class="header-anchor" href="#как-собрать-полезныи-отчет" aria-label="Permalink to “Как собрать полезный отчёт”">​</a></h2><p>Хороший отчёт экономит один круг переписки. Достаточно пяти пунктов:</p><ol><li><strong>Что делали.</strong> «Открыл редактор, нажал “Загрузить полигоны”, перетащил <code>kadastr.zip</code>, выбрал дату 12-11-2026».</li><li><strong>Что ожидали.</strong> «Полигоны появятся в блокноте за эту дату».</li><li><strong>Что получилось.</strong> «Окно закрылось, в блокноте пусто, в консоли ошибка».</li><li><strong>Окружение.</strong> Версия расширения (настройки → номер версии), браузер и его версия, ОС.</li><li><strong>Доказательства.</strong> Скриншот окна и консоли, при возможности — сам файл (если в нём нет закрытых данных).</li></ol><h2 id="где-взять-версию" tabindex="-1">Где взять версию <a class="header-anchor" href="#где-взять-версию" aria-label="Permalink to “Где взять версию”">​</a></h2><p>В попапе настроек внизу показан номер версии; он же ведёт на страницу релизов. История изменений — в разделе <a href="/yamapper/versions">«Версии»</a>.</p><h2 id="что-делать-с-ошибкои-в-консоли" tabindex="-1">Что делать с ошибкой в консоли <a class="header-anchor" href="#что-делать-с-ошибкои-в-консоли" aria-label="Permalink to “Что делать с ошибкой в консоли”">​</a></h2><ol><li>Откройте <code>n.maps.yandex.ru</code>.</li><li><code>F12</code> → вкладка Console.</li><li>Отфильтруйте строки по <code>nmap</code> — так видны сообщения расширения.</li><li>Скопируйте текст ошибки целиком: обрезанный фрагмент часто бесполезен.</li></ol><p>Если ошибка воспроизводится в приватном окне — проверьте, не конфликтует ли расширение с другим установленным расширением для Народной карты. Отключите остальные и повторите.</p><h2 id="privacy" tabindex="-1">Приватность <a class="header-anchor" href="#privacy" aria-label="Permalink to “Приватность”">​</a></h2><ul><li><strong>Что пишется на Диск.</strong> Только две папки приложений: <code>Приложения/Блокнот картографа Народной карты</code> (загруженные геоданные) и <code>Приложения/Nmap Uploader</code> (заметки и их иконки). Остальные файлы не читаются и не изменяются.</li><li><strong>Где хранится токен.</strong> В локальном хранилище браузера, до выхода из аккаунта. Отозвать доступ можно в <a href="https://id.yandex.ru/" target="_blank" rel="noreferrer">настройках Яндекс ID</a>.</li><li><strong>Где обрабатываются файлы.</strong> Геоданные конвертируются на вашем устройстве; на Диск уходит только готовый <code>index.json</code>.</li><li><strong>Куда идут запросы.</strong> Только домены из манифеста: <code>n.maps.yandex.ru</code>, API Яндекс Диска и OAuth, <code>nakarte.me</code>, а также <code>nspd.gov.ru</code> при включённой загрузке из НСПД.</li><li><strong>Шрифт интерфейса.</strong> Подгружается с официального CDN <code>yastatic.net</code> — те же файлы, что использует редактор; без сети интерфейс остаётся на системном шрифте.</li></ul><h2 id="чего-не-делаем" tabindex="-1">Чего не делаем <a class="header-anchor" href="#чего-не-делаем" aria-label="Permalink to “Чего не делаем”">​</a></h2><ul><li>Не помогаем с доступом к закрытым данным и не запрашиваем пароль от Яндекс ID.</li><li>Не просим присылать токен доступа: он хранится в браузере и не нужен для диагностики.</li><li>Не публикуем найденные уязвимости до исправления.</li></ul>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};